use xiom.io;
use xiom.math;
fn random_character() -> Str {
  let characters = ["a wizard", "a cat", "a robot", "a pirate"];
  let index = math.random_range(0, 3);
  return characters[index];
}

fn random_place() -> Str {
  let places = ["a castle", "the moon", "a spaceship", "a forest"];
  let index = math.random_range(0, 3);
  return places[index];
}

fn random_action() -> Str {
  let actions = ["discovered a treasure", "baked a giant cake", "fought a dragon", "sang an opera"];
  let index = math.random_range(0, 3);
  return actions[index];
}

fn main() {
  let hero = random_character();
  let location = random_place();
  let deed = random_action();
  io.println("Once upon a time...");
  io.println("Your random story is ready!");
}
